// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.acceptedAnswers ? {acceptedAnswers: row.acceptedAnswers} : {}),
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(row.textAnswer !== undefined ? {textAnswer: row.textAnswer} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(row.acceptedNumericAnswers ? {acceptedNumericAnswers: row.acceptedNumericAnswers} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + (group.originalNumbers ? group.start : 1)), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.solutionsFile ? {solutionUrl: folder + meta.solutionsFile} : {}),
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"kit","year":2017,"grade":"10-11","contest":"КИТ","letters":"АБВГ","count":26,"language":"ru","points":3,"tasksFile":"10-11.pdf","answersFile":"reviewed-10-11.pdf","sections":[{"start":1,"title":"3 балла · № 1–5"},{"start":6,"title":"3 балла · № 6–10"},{"start":11,"title":"4 балла · № 11–15"},{"start":16,"title":"4 балла · № 16–20"},{"start":21,"title":"5 баллов · № 21–23"},{"start":24,"title":"Числовой ответ · № 24–26"}],"reviewedKey":true}, [{"title":"Печать большого формата","question":"Как называется устройство для печати на бумаге большого формата?","choices":["плоттер","сканер","трекбол","гироскоп"],"points":3,"steps":["Для больших карт и чертежей нужно устройство, которое выводит изображение на широкий лист.","Плоттер печатает или рисует на таком листе. Сканер считывает изображение, трекбол управляет курсором, гироскоп измеряет вращение."],"answer":0},{"title":"Топология «шина»","question":"Выберите схему локальной сети с топологией типа «шина».","choices":["Схема А","Схема Б","Схема В","Схема Г"],"points":3,"steps":["У сети типа «шина» есть одна общая линия, к которой подключены все узлы. Данные передаются по этой линии.","На схеме Г кружки имеют короткие ответвления к одной линии. В А получается кольцо, в Б звезда, в В сетка соединений."],"answer":3,"optionFigures":[{"src":"assets/kit/2017/10-11-02-a.webp","alt":"Четыре узла на контуре квадрата.","width":111,"height":105},{"src":"assets/kit/2017/10-11-02-b.webp","alt":"Четыре узла вокруг центрального.","width":111,"height":107},{"src":"assets/kit/2017/10-11-02-c.webp","alt":"Четыре узла соединены по сторонам и диагоналям.","width":111,"height":107},{"src":"assets/kit/2017/10-11-02-d.webp","alt":"Четыре узла присоединены ответвлениями к одной прямой линии.","width":162,"height":108}]},{"title":"Аппарат с четырьмя винтами","question":"В 1922 году Георгий Ботезат построил один из первых вертолётов в мире. У этого вертолёта было 4 винта. Сегодня подобные аппараты мы называем…","choices":["квадрокоптерами","планерами","квадроциклами","вентиляторами"],"points":3,"steps":["Вопрос о летательном аппарате, который поднимается за счёт четырёх несущих винтов.","В слове «квадрокоптер» первая часть указывает на четыре винта. Планер и другие варианты устроены иначе."],"answer":0,"figure":{"src":"assets/kit/2017/10-11-03.webp","alt":"Историческая чёрно-белая фотография аппарата Ботезата с четырьмя несущими винтами.","width":384,"height":174}},{"title":"Выигрышные клетки","question":"Сколько выигрышных полей у «крестиков»? Выигрышным называется поле, сходив на которое, при любых ответах «ноликов» «крестики» имеют возможность победить.","choices":["1","2","3","4"],"points":3,"steps":["Пронумеруй ряды снизу. Крестик в В2 создаёт две угрозы по диагоналям между углами. Крестик в А1 создаёт угрозу по столбцу А и по диагонали А1–В2–С3.","За один ответ соперник не может закрыть две угрозы. У остальных ходов такой гарантии нет: угрозу можно закрыть или выиграть самому. Выигрышных клеток две."],"answer":1,"figure":{"src":"assets/kit/2017/10-11-04.svg","alt":"Крестики в верхних углах, нолики в верхней центральной и правой клетке среднего ряда.","width":168,"height":168}},{"title":"Папка удалённых файлов","question":"В зависимости от версии Windows в корневом каталоге диска есть папка, называемая, например, RECYCLED, RECYCLER или $RECYCLE.BIN. В эту папку файлы попадают при использовании элемента графического интерфейса…","choices":["мои документы","корзина","мой компьютер","мои рисунки"],"points":3,"steps":["В названиях папок есть recycle, а $RECYCLE.BIN — служебный каталог Windows для временно удалённых файлов.","Когда пользователь удаляет файл в корзину, Windows хранит его в таком каталоге, пока файл не восстановили или корзину не очистили."],"answer":1},{"title":"Доли на диаграммах","question":"Какая круговая диаграмма соответствует столбчатой?","choices":["Рисунок А","Рисунок Б","Рисунок В","Рисунок Г"],"points":3,"steps":["Столбцы A, B, C имеют высоты 5, 10 и 15, сумма 30. Значит, A занимает 1/6, B — 1/3, C — 1/2 всей площади.","Нужна половина круга под C и вдвое меньшая доля A сравнительно с B. Так подписана диаграмма Б."],"answer":1,"figure":{"src":"assets/kit/2017/8-9-10.svg","alt":"Столбцы A = 5, B = 10, C = 15.","width":207,"height":204},"optionFigures":[{"src":"assets/kit/2017/8-9-10-a.webp","alt":"Три равных сектора.","width":171,"height":171},{"src":"assets/kit/2017/8-9-10-b.webp","alt":"C занимает половину, B треть, A шестую часть.","width":174,"height":171},{"src":"assets/kit/2017/8-9-10-c.webp","alt":"C больше половины, A и B равные сектора.","width":168,"height":171},{"src":"assets/kit/2017/8-9-10-d.webp","alt":"C немного больше трети, A четверть.","width":177,"height":171}]},{"title":"Обмен сообщениями","question":"Что не относится к системе мгновенного обмена сообщениями?","choices":["WhatsApp","ICQ","Viber","The Bat!"],"points":3,"steps":["Первые три предназначены для коротких сообщений, которые собеседники отправляют друг другу в реальном времени.","The Bat! — программа для работы с электронной почтой. Она загружает и отправляет письма по почтовым протоколам."],"answer":3},{"title":"Память без питания","question":"После выключения компьютера пропадает информация, находящаяся…","choices":["в оперативной памяти","на жёстком диске","на USB-флеш-накопителе","на CD-диске"],"points":3,"steps":["Оперативная память хранит рабочие данные, пока на неё подаётся питание. После выключения эти данные теряются.","Жёсткий диск, флешка и компакт-диск хранят файлы и без питания."],"answer":0},{"title":"Степени двойки и байты","question":"Выберите наибольшее значение.","choices":["1 Кбит","2¹⁴ бит","2¹² байт","1 Кбайт"],"points":3,"steps":["Переведи байты в биты. В одном байте 8 = 2³ бита. Поэтому 2¹² байт — это 2¹⁵ бит.","2¹⁵ больше 2¹⁴. Один килобайт и один килобит ещё меньше. Наибольшее значение — 2¹² байт."],"answer":2},{"title":"Механическое вычисление","question":"Сколько механических (то есть не имеющих электронных компонентов) вычислительных устройств показано на рисунке?","choices":["1","2","3","4"],"points":3,"steps":["Калькулятор, телефон, электронные весы, ноутбук и проектор используют электронные компоненты.","Только счёты работают перемещением косточек по спицам. Это одно механическое вычислительное устройство."],"answer":0,"figure":{"src":"assets/kit/2017/10-11-10.webp","alt":"Слева направо цифровой калькулятор, счёты, телефон, электронные весы, ноутбук и проектор.","width":1146,"height":186}},{"title":"Перенос в двоичной записи","question":"Алгоритм преобразования числа, записанного в двоичной системе счисления, состоит в том, что если последняя цифра числа 0, то она заменяется на 1. Иначе весь набор подряд идущих в конце числа единиц заменяется нулями, а 0, стоящий слева от этого набора, заменяется на 1. Наконец, если в исходном числе нет ни одной цифры 0, то все 1 заменяются на 0, а слева от них записывается 1. Этот алгоритм исходное число увеличивает…","choices":["на 1","вдвое","вдесятеро","в 8 раз"],"points":4,"steps":["Последний разряд имеет вес 1. Если в нём 0, то замена на 1 увеличивает число на единицу без переноса.","Если там 1, при сложении возникает перенос через цепочку единиц. Алгоритм выполняет ровно такое же обнуление и ставит 1 в первом свободном разряде. Прибавляется 1."],"answer":0},{"title":"Числовая таблица","question":"Петя случайно удалил значения некоторых ячеек электронной таблицы. Известно, что сумма чисел в каждой строке, каждом столбце и на обеих диагоналях одинакова. Какое число было записано в ячейке C2?\n\nВ A1 стоит 8, в C1 стоит 4. В B2 формула =B1+2, в A3 формула =2*B1.","choices":["6","7","9","4"],"points":4,"steps":["Если в B1 стоит x, то сумма первой строки 12 + x, а центр x + 2. Сумма каждой линии равна утроенному центру: 12 + x = 3(x + 2). Отсюда x = 3, центр 5, сумма 15.","В A3 записано 2x = 6. Первый столбец даёт A2 = 15 − 8 − 6 = 1. Тогда C2 = 15 − 1 − 5 = 9."],"answer":2},{"title":"Три языка у участников","question":"Рабочими языками олимпиады по программированию являются Паскаль, Бейсик и C++. В анкете 25 человек указали владение Паскалем, 20 — Бейсиком, а 11 — C++. Какое наибольшее число участников могут владеть тремя языками программирования, если участников 35 человек?","choices":["20","25","10","11"],"points":4,"steps":["Всего отметок 56, участников 35. Каждый знает хотя бы один язык. Лишних отметок 21. У владеющего тремя языками две лишние отметки, значит, таких участников не больше десяти.","Можно распределить так: десять владеют всеми тремя, один Паскалем и Бейсиком, четырнадцать только Паскалем, девять только Бейсиком, один только C++. Всего 35 с нужными итогами."],"answer":2},{"title":"Китайская запись числа","question":"В Китае число 400 записывают как 四百, 440 — как 四百四十, 404 — как 四百〇四. Какое из чисел может обозначать 4004?","choices":["四千四百〇四","四千〇四","四千四百四十","四千四十〇四"],"points":4,"steps":["Четыре тысячи записываются как 四千. В числе 4004 нет ни сотен, ни десятков, а в конце четыре единицы.","Как в образце 404, символ 〇 отмечает пропуск разрядов. Соединяем 四千 и 〇四, получается 四千〇四."],"answer":1},{"title":"Корень за дробью","question":"Для записи формулы a = 12/(4 · √9) в системе вёрстки математических формул TeX необходимо набрать $a=\\frac{12}{4\\cdot\\sqrt{9}}$. Если дана запись $b=\\frac{12}{4}\\cdot\\sqrt{9}$, то значение b равно…","choices":["1","6","3","9"],"points":4,"steps":["Команда \\frac{12}{4} даёт дробь 12/4. Команда \\sqrt{9} за ней даёт 3.","Знак умножения стоит после дроби, поэтому 12/4 умножается на 3. Получаем 9."],"answer":3},{"title":"Совпадающие разряды","question":"Алина задумала четырёхзначное число из цифр 1, 2, 3, 4. У задуманного числа и числа 1243 одинаковая цифра стоит в двух разрядах, а у задуманного числа и числа 2143 одинаковых цифр в совпадающих разрядах нет. Какое число задумала Алина?","choices":["1432","4321","2134","1234"],"points":4,"steps":["У 1243 и 2143 одинаковые последние две цифры. С загаданным числом 2143 не совпадает вовсе, значит оба совпадения с 1243 — в начале.","Загаданное начинается на 12. Для последних мест остаются 3 и 4. Третья цифра не может быть 4 из-за 2143. Выходит 1234."],"answer":3},{"title":"Переставленные смайлики","question":"За какое минимальное количество перестановок из последовательности :))::)):): можно получить максимальное количество смайликов :)? Под перестановкой понимается замена друг на друга двух непересекающихся фрагментов последовательности одинаковой длины.","choices":["1","2","3","4"],"points":4,"steps":["В строке по пять двоеточий и скобок. Пять смайликов требуют точной строки :):):):):). Для обменов блоков длины 1, 2, 3, 4 или 5 перебор всех пар начальных позиций даёт соответственно максимум 4, 4, 4, 4 и 2 смайлика.","Обменяй позиции 2 и 5, получишь ::):))):):. Затем поменяй местами блоки длины 4 с началами в позициях 2 и 7. Выходит пять смайликов за два обмена."],"answer":1},{"title":"Раскраска областей","question":"Каждую область на рисунке необходимо закрасить каким-то цветом так, чтобы области, имеющие общую границу, были закрашены в разные цвета. Каким наименьшим числом красок можно обойтись?","choices":["5","6","3","4"],"points":4,"steps":["Большой области с выемкой внизу дадим цвет 1, прямоугольнику в выемке — цвет 2. Из трёх прямоугольников над ними два крайних касаются обоих цветов и требуют цвета 3. Средний касается 2 и 3, значит он 1.","Правая Г-образная область касается 1 и 3, она цвета 2. Верхняя левая теперь касается всех трёх цветов и требует четвёртого. Левому вертикальному краю можно дать цвет 2. Хватает четырёх."],"answer":3,"figure":{"src":"assets/kit/2017/8-9-21.svg","alt":"Восемь областей: правая Г-образная, большая нижняя с выемкой, один прямоугольник в выемке и три над ней, верхняя левая и левый вертикальный край.","width":339,"height":222}},{"title":"Числа по примерам","question":"Системы счисления подразделяются на позиционные (например, двоичная, десятичная) и непозиционные. В последних число однозначно определяется только своими «цифрами», а порядок записи «цифр» числа не важен. Юра придумал свою непозиционную систему для записи чисел от 1 до 1023. В ней, например, число 2 записывается как 1, 4 — как 2, 16 — как 4, 32 — как 5, 48 — как 45 (или 54), 50 — как 145 (или 415 и т. д.). Какому числу соответствует запись 26?","choices":["24","26","62","68"],"points":4,"steps":["Цифры в этой записи обозначают показатели степеней двойки. Число 45 означает 2⁴ + 2⁵, что даёт 48.","Для 26 складываем 2² и 2⁶. Получается 4 + 64 = 68."],"answer":3},{"title":"Два обнуления массива","question":"Вася составил алгоритм, который заполняет одномерный целочисленный массив из 100 ячеек (нумерация ячеек с 0) последовательными натуральными числами, начиная с 1. Затем алгоритм обнуляет все ячейки с нечётными простыми числами. Затем алгоритм обнуляет все ячейки, чей индекс кратен содержимому третьей непустой (не содержащей ноль) с начала массива ячейки. Какое число хранится в ячейке с индексом 18?","choices":["0","17","18","19"],"points":4,"steps":["При нумерации с нуля в ячейку с индексом 18 записывают 19. Оно простое и нечётное, значит, первый этап заменяет его нулём.","Остальные операции только обнуляют дополнительные клетки. Они не могут вернуть прежнее значение ячейки 18, там останется 0."],"answer":0},{"title":"Объём фотографии","question":"Вася отсканировал цветную фотографию размером 5,08 см на 5,08 см. Параметры сканирования: цветопередача — 65536 цветов, разрешение 512 dpi. Формат файла, в котором он сохранил фотографию, не использует сжатие. Чему равен объём полученного файла в мегабайтах?","choices":["1","2","8","16"],"points":5,"steps":["5,08 см — ровно два дюйма. При 512 точках на дюйм каждая сторона содержит 1024 пикселя. Цветов 65536 = 2¹⁶, значит, на пиксель нужно 16 бит, или два байта.","Объём пиксельных данных 1024 × 1024 × 2 байта. При двоичном счёте мегабайтов это 2 Мбайт."],"answer":1},{"title":"Все разводные мосты","question":"Кружками на рисунке обозначены острова, а линиями — разводные мосты, все они сведены. На какой-то остров высаживают рабочего, который должен развести наибольшее количество мостов. Перейдя мост, рабочий на своё усмотрение либо разводит его, либо оставляет сведённым. Сколько мостов будет разведено?","choices":["6","7","8","5"],"points":5,"steps":["Обозначь углы А, Б, В, Г по часовой стрелке и центр О. Пока оставь сведёнными мосты пути А–Б–О–В–Г. По ним пока можно попасть на любой остров.","Сначала последовательно разводи остальные четыре моста. Между ними можно переходить по оставленному пути. Затем приди в А и пройди до Г по оставленному пути, разводя все его мосты. Так разведены все восемь."],"answer":2,"figure":{"src":"assets/kit/2017/4-5-22.svg","alt":"Четыре угла прямоугольника соединены по периметру. Каждый угол соединён с центром.","width":324,"height":231}},{"title":"Действия на линейке","question":"На рисунке представлена часть логарифмической линейки, в которой шкалы выставлены для вычисления произведения 1,2 · 1,3. Результат какого действия невозможно увидеть из представленного на рисунке положения шкал?","choices":["1,2 · 15","1,2 + 2","12 · 25","2,4 : 2"],"points":5,"steps":["На логарифмической шкале расстояния соответствуют логарифмам. Сдвиг шкалы складывает или вычитает логарифмы, что даёт произведение или частное чисел.","Сама шкала не складывает обычные значения. Из данных вариантов таким действием является 1,2 + 2."],"answer":1,"figure":{"src":"assets/kit/2017/10-11-23.svg","alt":"Две строки логарифмических шкал со сдвигом, отмечены цифры и π.","width":822,"height":204}},{"title":"Крючки для букв","question":"Аскар, который учится писать буквы «ш» и «и», написал несколько букв, как на рисунке. Сколькими способами можно прочитать эти буквы, используя всю строку целиком?","choices":[],"points":5,"steps":["Для 14 крючков число трёхкрючковых «ш» должно быть чётным. Подходят 0, 2 и 4 буквы «ш», а «и» соответственно 7, 4 и 1.","При нуле «ш» порядок один. При двух — выбери два места из шести, 15 способов. При четырёх — выбери место единственной «и» из пяти. Всего 1 + 15 + 5 = 21."],"numericAnswer":21,"figure":{"src":"assets/kit/2017/8-9-24.webp","alt":"Последовательность из четырнадцати одинаковых крючков.","width":426,"height":72}},{"title":"Две открытки одного города","question":"Имеется 16 открыток с живописными видами 8 городов (по 2 открытки на один город), расположенных картинками вниз. Перевернули две произвольные открытки. Сколько бит информации содержит сообщение о том, что на них виды одного и того же города? Если ответ не целый, то полученное число округлите в большую сторону.","choices":[],"points":5,"steps":["После выбора первой открытки из 15 оставшихся только одна показывает тот же город. Вероятность совпадения равна 1/15.","Информация такого сообщения равна log₂15. Это между 3 и 4, поскольку 8 < 15 < 16. Округляем вверх, получаем 4 бита."],"numericAnswer":4},{"title":"Порядок обхода лабиринта","question":"Имеется глобальный символьный двумерный массив m (6 × 6), представленный ниже, у которого индексация строк и столбцов начинается с 0. Глобальная целочисленная переменная count_ изначально равна нулю. Код функции find_p() написан на языке C++ и приведён ниже. Чему будет равно значение глобальной переменной count_ после вызова find_p(0, 0)?\n\nS...##\n#.#...\n..#..#\n..###.\n#...##\n###..F\n\nfind_p(int x, int y){\n  if (x < 0 || x > 5 || y < 0 || y > 5) return 0;\n  if (m[y][x] == 'F') return 1;\n  if (m[y][x] != '.' && m[y][x] != 'S') return 0;\n  m[y][x] = '+';\n  count_++;\n  if(find_p(x, y − 1)) return 1;\n  if(find_p(x + 1, y)) return 1;\n  if(find_p(x, y + 1)) return 1;\n  if(find_p(x − 1, y)) return 1;\n  m[y][x] = 'x';\n  return 0;\n}","choices":[],"points":5,"steps":["Считаются только впервые посещённые клетки S и точки. Порядок проверки соседей: вверх, вправо, вниз, влево. Сначала пройдут (0,0), (1,0), (2,0), (3,0), (3,1), (4,1), (5,1), (4,2), (3,2). Эта ветвь до финиша не доходит.","Вернувшись к (1,0), программа посетит (1,1), (1,2), (1,3), (1,4), (2,4), (3,4), (3,5), (4,5) и найдёт F в (5,5). F проверяется до увеличения счётчика. Получаем 9 + 8 = 17."],"numericAnswer":17}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
